// #190a63 (81c0182b234c10aeac190a63) — «ל-» перед именем на латинице или с цифры в сообщениях продления/новой ссылки
// (было «לQA-…»); перед ивритом — слитно, без дефиса. Кейс CAND-012.
// Данные: три кандидата business testim (только ссылка, link_only — ничего не отправляется) с постоянными именами
// QA-AUTO-190a63 / «2110 QA-AUTO-190a63» / «בדיקה QA-AUTO-190a63». Создаются один раз, если их нет, и переиспользуются
// (кандидата удалить нельзя — так не копятся новые записи). Тест меняет их ссылки → @data, файл по порядку (serial):
// сначала новая ссылка (делает ссылку активной), потом продление, потом новая ссылка из /admin/support.
// «איפוס ניסיון» — подмена (list_candidates: попытка completed; reset_attempt → ok), реальный сброс не выполняется.
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { listCandidates } from './hiring-support';
import { createCandidateLink } from '../candidate-call/support';

test.describe.configure({ mode: 'serial' });

const HASH = '#190a63 · #81c0182b234c10aeac190a63';
const REASON = 'QA-AUTO-190a63 בדיקת נוסח';

const NAMES = [
  { kind: 'латиница', name: 'QA-AUTO-190a63', le: 'ל-QA-AUTO-190a63', wrong: 'לQA-AUTO-190a63' },
  { kind: 'цифра', name: '2110 QA-AUTO-190a63', le: 'ל-2110 QA-AUTO-190a63', wrong: 'ל2110 QA-AUTO-190a63' },
  { kind: 'иврит', name: 'בדיקה QA-AUTO-190a63', le: 'לבדיקה QA-AUTO-190a63', wrong: 'ל-בדיקה QA-AUTO-190a63' },
];

async function idsByName(page: Page): Promise<Record<string, string>> {
  const api = await openWithApi(page, '/candidates');
  const all = await listCandidates(api);
  const out: Record<string, string> = {};
  for (const n of NAMES) {
    const found = all.filter((c) => c.full_name === n.name);
    expect(found.length, `больше одного кандидата «${n.name}»`).toBeLessThanOrEqual(1);
    if (found.length) out[n.name] = found[0].id;
  }
  return out;
}

/** Кандидаты с постоянными именами: создать недостающих (link_only). */
async function ensureCandidates(page: Page): Promise<Record<string, string>> {
  let ids = await idsByName(page);
  for (const n of NAMES) if (!ids[n.name]) await createCandidateLink(page, n.name);
  ids = await idsByName(page);
  for (const n of NAMES) expect(ids[n.name], `кандидат «${n.name}» не создан`).toBeTruthy();
  return ids;
}

/** /candidates с поиском по имени (поиск по «QA-AUTO-190a63» находит все три — кнопку берём по точной подписи). */
async function openList(page: Page, name: string) {
  await page.goto('/candidates');
  await expect(page.getByRole('heading', { level: 1, name: 'מועמדים' })).toBeVisible();
  const search = page.getByRole('searchbox').or(page.getByPlaceholder(/חיפוש/)).first();
  if (await search.isVisible()) await search.fill(name);
}

const dialogWith = (page: Page, text: string | RegExp) =>
  page.locator('[role=dialog],[role=alertdialog]').filter({ hasText: text }).last();

test.describe(`Кандидаты — «ל-» перед латиницей/цифрой в сообщениях о ссылке (${HASH})`, () => {
  let ids: Record<string, string> = {};

  test.beforeAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/business.json'), viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    ids = await ensureCandidates(page);
    await ctx.close();
  });

  test(`business: отчёт → «ניהול הקישור» → «הפקת קישור חדש»: заголовок и уведомление с «ל-» перед латиницей/цифрой, слитно перед ивритом @desktop @data ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    for (const n of NAMES) {
      await page.goto(`/candidates/${ids[n.name]}/report`);
      await page.getByRole('button', { name: 'ניהול הקישור' }).click();
      await page.getByRole('button', { name: 'הפקת קישור חדש', exact: true }).first().click();

      // Источник: «מה רצוי» #190a63 — «ל-» перед латиницей и цифрой, перед ивритом без дефиса.
      const dialog = dialogWith(page, 'להפיק קישור חדש');
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText(`להפיק קישור חדש ${n.le}?`);
      await expect(dialog).not.toContainText(n.wrong);

      const [res] = await Promise.all([
        page.waitForResponse((r) => /rpc\/reissue_candidate_link/.test(r.url())),
        dialog.getByRole('button', { name: 'הפקת קישור חדש' }).click(),
      ]);
      expect(res.status(), `${n.name}: reissue_candidate_link`).toBe(200);
      await expect(page.getByText(`נוצר ${n.le} קישור חדש בתוקף ליומיים`).first()).toBeVisible();
      await expect(page.getByText(`נוצר ${n.wrong} `)).toHaveCount(0);
    }
  });

  test(`business: /candidates → «הארכת תוקף ב־2 ימים» → «הארכת התוקף»: уведомление «נוצר ל-…» / «נוצר לבדיקה…» @desktop @data ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    for (const n of NAMES) {
      await openList(page, n.name);
      await page.getByRole('button', { name: `הארכת תוקף ב־2 ימים: ${n.name}`, exact: true }).click();
      const dialog = dialogWith(page, 'להאריך את תוקף הקישור');
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText(`להאריך את תוקף הקישור של ${n.name}?`);

      const [res] = await Promise.all([
        page.waitForResponse((r) => /rpc\/extend_candidate_link/.test(r.url())),
        dialog.getByRole('button', { name: 'הארכת התוקף' }).click(),
      ]);
      expect(res.status(), `${n.name}: extend_candidate_link`).toBe(200);
      // Источник: «מה רצוי» #190a63.
      await expect(page.getByText(`נוצר ${n.le} קישור חדש בתוקף ליומיים`).first()).toBeVisible();
      await expect(page.getByText(`נוצר ${n.wrong} `)).toHaveCount(0);
    }
  });

  test(`admin: /admin/support → «⋮» → «הפקת קישור חדש»: заголовок и уведомление с «ל-» (латиница, цифра) @desktop @data ${HASH}`, async ({ asUser }) => {
    const page = await asUser('admin');
    for (const n of NAMES.filter((x) => x.kind !== 'иврит')) {
      await page.goto('/admin/support');
      const row = page.getByRole('row').filter({ has: page.getByText(n.name, { exact: true }) }).first();
      await expect(row, `нет строки «${n.name}» в /admin/support`).toBeVisible({ timeout: 30_000 });
      await row.getByRole('button', { name: /^פעולות/ }).click();
      await page.getByRole('menuitem', { name: /הפקת קישור חדש/ }).click();

      const dialog = dialogWith(page, 'להפיק קישור חדש');
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText(`להפיק קישור חדש ${n.le}?`);
      await expect(dialog).not.toContainText(n.wrong);
      const reason = dialog.getByRole('textbox');
      if (await reason.count()) await reason.first().fill(REASON);

      const [res] = await Promise.all([
        page.waitForResponse((r) => /reissue/.test(r.url()) && r.request().method() === 'POST'),
        dialog.getByRole('button', { name: /הפקת קישור חדש/ }).last().click(),
      ]);
      expect(res.status(), `${n.name}: reissue (admin)`).toBe(200);
      // Источник: «מה רצוי» #190a63.
      await expect(page.getByText(`נוצר ${n.le} קישור חדש בתוקף ליומיים`).first()).toBeVisible();
    }
  });

  test(`business: «איפוס ניסיון» (подмена ответа, без реального сброса): «נוצר קישור חדש ל-…, והסימולציה…» @desktop @data ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const hits: string[] = [];
    // Попытка показана как завершённая, чтобы была кнопка «איפוס ניסיון»; сам сброс подменён → данные не меняются.
    await page.route('**/rest/v1/rpc/list_candidates', async (route) => {
      const res = await route.fetch();
      const list = await res.json();
      for (const c of Array.isArray(list) ? list : []) {
        if (NAMES.some((n) => n.name === c.full_name)) {
          c.attempt = { id: '00000000-0000-0000-0000-0000000190a6', status: 'completed', end_reason: 'candidate_ended', attempt_type: 'official' };
          c.execution_status = 'completed';
          if (c.invite) c.invite.status = 'completed';
        }
      }
      await route.fulfill({ response: res, json: list });
    });
    await page.route('**/rest/v1/rpc/reset_attempt', async (route) => {
      hits.push(route.request().postData() || '');
      await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ ok: true }) });
    });

    for (const n of NAMES) {
      await openList(page, n.name);
      await page.getByRole('button', { name: `איפוס ניסיון: ${n.name}`, exact: true }).click();
      const dialog = page.locator('[role=dialog],[role=alertdialog]').filter({ has: page.getByLabel('סיבת האיפוס') }).last();
      await expect(dialog).toBeVisible();
      await dialog.getByLabel('סיבת האיפוס').fill(REASON);
      await dialog.getByLabel('אני מאשר/ת את האיפוס כאישור חריג').check();
      await dialog.getByRole('button', { name: /איפוס/ }).last().click();

      // Источник: «מה רצוי» #190a63.
      await expect(page.getByText(`נוצר קישור חדש ${n.le}, והסימולציה תתחיל מתחילת התרחיש`).first()).toBeVisible();
      await expect(page.getByText(`נוצר קישור חדש ${n.wrong},`)).toHaveCount(0);
    }
    expect(hits, 'reset_attempt вызван по разу на кандидата (подменён)').toHaveLength(NAMES.length);
  });
});
